-- Execute em um banco de demonstração dedicado. Substitui somente dbo.chamados.
SET XACT_ABORT ON;
BEGIN TRANSACTION;
IF OBJECT_ID('dbo.chamados', 'U') IS NOT NULL DROP TABLE dbo.chamados;
CREATE TABLE dbo.chamados (
 id int NOT NULL PRIMARY KEY, filial nvarchar(100) NOT NULL, categoria nvarchar(100) NOT NULL,
 prioridade nvarchar(20) NOT NULL, aberto_em datetime2(3) NOT NULL, resolvido_em datetime2(3) NULL,
 prazo_horas int NOT NULL CHECK (prazo_horas > 0), status nvarchar(20) NOT NULL,
 CONSTRAINT CK_chamados_status CHECK ((status = N'aberto' AND resolvido_em IS NULL) OR (status = N'resolvido' AND resolvido_em >= aberto_em))
);
COMMIT TRANSACTION;
